    {
        m_plater = m_app.plater();
        check(m_plater != nullptr, "crash_plater_ready");
        if (!m_plater) return;
        check(m_plater->new_project(true, true) != wxID_CANCEL, "crash_new_project");
        if (m_state->mode == HarnessState::Mode::CrashWrite) {

