    if (!path.empty()) {
        FileLoadRecord load;
        load.files         = {path};
        load.with_settings = opened;
        load.messages      = m_load_messages;
        report.loads.push_back(std::move(load));
    }
    if (opened)
        report.details = m_details;
    return report;
