    CHECK(pattern["applied"] == json{{"start", 0.}, {"end", 1.}, {"step", 0.05}, {"method", "pattern"}, {"extruderType", "bowden"}});
    CHECK(h.workspace.last_calibration.method == Workspace::PressureAdvanceMethod::Pattern);
    const json flow = json::parse(settle(submit(json{{"test", "flow"}})).result_json);
    CHECK(flow["applied"] == json{{"pass", 1}, {"linear", true}});
    CHECK(flow["objects"].size() == 2);
    CHECK(summaries.size() == 3);

    // A project that cannot be saved stays open, and no chat is told.
    h.workspace.calibration_release_fails = true;
    const std::uint64_t before = h.workspace.snapshot().session.value();
    const ToolActivity kept = settle(submit(json{{"test", "flow"}}));
    REQUIRE(kept.error.has_value());
    CHECK(kept.error->code == "unavailable_operation");
    CHECK(h.workspace.snapshot().session.value() == before);
    CHECK(summaries.size() == 3);
}

