2161	    // A person's project with one object and an unsaved filament edit of
2162	    // their own, named so its version can be found after it is closed.
2163	    // Returns the edited first nozzle temperature.
2164	    int person_project_with_unsaved_edit(const std::string& name)
2165	    {
2166	        check(m_plater->new_project(true, true) != wxID_CANCEL, name + "_new_project");
2167	        const std::string cube = std::string(JUSPRIN_SOURCE_DIR) + "/tests/data/test_stl/ASCII/20mmbox-LF.stl";
2168	        check(m_plater->load_files(std::vector<std::string>{cube},
2169	                                   LoadStrategy::LoadModel | LoadStrategy::AddDefaultInstances | LoadStrategy::Silence, false)
2170	                      .size() == 1,
2171	              name + "_cube_loaded");
2172	        m_plater->set_project_name(from_u8(name));
2173	        PresetCollection&  filaments = m_app.preset_bundle->filaments;
2174	        DynamicPrintConfig edited    = filaments.get_edited_preset().config;
2175	        auto&              values    = edited.option<ConfigOptionInts>("nozzle_temperature")->values;
2176	        for (int& value : values) value = (value == 223 ? 224 : 223);
2177	        m_app.get_tab(Preset::TYPE_FILAMENT)->load_config(edited);
2178	        check(filaments.current_is_dirty(), name + "_unsaved_filament_edit");
2179	        return values.front();
2180	    }
