2182	    // The newest version saved of a managed project, by its name: one
2183	    // setting as its project_settings.config holds it.
2184	    std::string saved_project_setting(ProjectAutosave& autosave, const std::string& project, const std::string& key)
2185	    {
2186	        for (const auto& managed : autosave.projects()) {
2187	            if (managed.name != project)
2188	                continue;
2189	            std::filesystem::path newest;
2190	            std::error_code       error;
2191	            for (const auto& entry : std::filesystem::directory_iterator(std::filesystem::u8path(managed.store_path) / "versions", error))
2192	                if (std::filesystem::is_regular_file(entry.path() / "metadata.3mf") &&
2193	                    (newest.empty() || entry.last_write_time() > std::filesystem::last_write_time(newest)))
2194	                    newest = entry.path();
2195	            std::cerr << "HARNESS CALIBRATION versions of \"" << project << "\": newest " << newest.filename().u8string() << '\n';
2196	            if (newest.empty())
2197	                return {};
2198	            mz_zip_archive archive;
2199	            mz_zip_zero_struct(&archive);
2200	            if (!open_zip_reader(&archive, (newest / "metadata.3mf").u8string()))
2201	                return {};
2202	            size_t size = 0;
2203	            void*  data = mz_zip_reader_extract_file_to_heap(&archive, "Metadata/project_settings.config", &size, 0);
2204	            close_zip_reader(&archive);
2205	            if (data == nullptr)
2206	                return {};
2207	            const auto config = nlohmann::json::parse(std::string(static_cast<const char*>(data), size));
2208	            mz_free(data);
2209	            const auto& value = config.value(key, nlohmann::json());
2210	            return value.is_array() && !value.empty() ? value.front().get<std::string>() : value.is_string() ? value.get<std::string>() : "";
