{
  "name": "jusprin-home-bridge",
  "version": 1,
  "capabilities": [
    "projects",
    "printers",
    "appearance",
    "project_actions",
    "printer_actions"
  ],
  "pageMessageTypes": [
    "hello",
    "state_request",
    "open_project",
    "new_project",
    "import_project",
    "launch_monitor",
    "add_printer",
    "connect_printer",
    "open_printer_settings",
    "rename_printer",
    "remove_printer"
  ],
  "hostMessageTypes": [
    "hello_ack",
    "hello_reject",
    "state",
    "projects",
    "printers",
    "appearance",
    "printer_error",
    "bridge_error"
  ]
}
  | 'open_project'
  | 'new_project'
  | 'import_project'
  | 'launch_monitor'
  | 'add_printer'
  | 'connect_printer'
  | 'open_printer_settings'
  | 'rename_printer'
  | 'remove_printer';

export type HostMessageType =
  | 'hello_ack'
  | 'hello_reject'
  | 'state'
  | 'projects'
  | 'printers'
  | 'appearance'
  | 'printer_error'
  | 'bridge_error';

export type Appearance = 'light' | 'dark';

// What a project card's status line means, separate from what it says. Only
// 'printing' earns a colored dot; every other state takes the plain line, so
// an idle project cannot be mistaken for a running one.
//
// 'unknown' means the local project store has no current slice state to report.
export type ProjectStatusKind = 'unknown' | 'draft' | 'sliced' | 'printing' | 'completed';

export interface ProjectStatus {
  kind: ProjectStatusKind;
  // Host-formatted and already translated; the page never composes it.
  text: string;
}

export interface ProjectInfo {
  id: string;
  name: string;
  // Shown only as a tooltip: the card is titled by name.
  path: string;
  // A preview URL, absent when the project carries none.
    [getTransport],
  );

  useEffect(() => {
    client.start();
  }, [client]);

  // Each action clears the last refusal first: its message was about the
  // previous request, not this one.
  const printerActions = useMemo<PrinterActions>(() => {
    const send = (type: 'open_printer_settings' | 'rename_printer' | 'remove_printer' | 'connect_printer', payload: object) => {
      dispatch({ kind: 'printer_action' });
      client.send(type, payload);
    };
    return {
      onConnect: (id) => send('connect_printer', { id }),
      onOpenSettings: (id) => send('open_printer_settings', { id }),
      onRename: (id, name) => send('rename_printer', name === undefined ? { id } : { id, name }),
      onRemove: (id) => send('remove_printer', { id }),
    };
  }, [client]);

  useEffect(() => {
    applyAppearance(state.appearance);
  }, [state.appearance]);

  if (state.connection !== 'connected' && !state.loaded) {
    return (
      <div className="app connecting">
        <h1>Connecting…</h1>
        <p>Starting Home.</p>
        {state.connectionDetail && (
          <details>
            <summary>Diagnostics</summary>
            <p className="footnote">{state.connectionDetail}</p>
          </details>
    else if (type == "open_project")
        m_backend.open_project(payload.value("id", std::string()));
    else if (type == "new_project")
        m_backend.new_project();
    else if (type == "import_project")
        m_backend.import_model();
    else if (type == "launch_monitor")
        m_backend.launch_monitor(payload.value("id", std::string()));
    else if (type == "add_printer") {
        m_backend.add_printer();
        push_state();
    }
    else if (type == "open_printer_settings" || type == "rename_printer" || type == "remove_printer" || type == "connect_printer") {
        const std::string id = payload.value("id", std::string());
        const std::string problem =
            type == "connect_printer"       ? m_backend.connect_printer(id)
            : type == "open_printer_settings" ? m_backend.open_printer_settings(id)
            : type == "rename_printer"      ? m_backend.rename_printer(id, payload.value("name", std::string()))
                                            : m_backend.remove_printer(id);
        if (!problem.empty())
            send("printer_error", json{{"id", id}, {"message", problem}}, correlation);
        // Each can change the rail, including when the person cancelled
        // halfway through an Orca prompt, so the page always gets it back.
        push_state();
    }
}

