// Drives calibration_generate and the settings tools end to end over MCP,
// through the bundled stdio bridge, as an external client would. Usage:
//   node mcp-calibration.mjs <jusprin-mcp.exe> <discovery mcp.json> <transcript.jsonl>
import { spawn } from 'node:child_process';
import { createInterface } from 'node:readline';
import { writeFileSync, appendFileSync } from 'node:fs';

const [bridgePath, discovery, transcript] = process.argv.slice(2);
writeFileSync(transcript, '');
const bridge = spawn(bridgePath, ['--discovery', discovery], { stdio: ['pipe', 'pipe', 'inherit'] });
const waiting = new Map();
createInterface({ input: bridge.stdout }).on('line', (line) => {
  const message = JSON.parse(line);
  if (message.id !== undefined && waiting.has(message.id)) {
    waiting.get(message.id)(message);
    waiting.delete(message.id);
  }
});
let next = 1;
function rpc(method, params = {}) {
  const id = next++;
  bridge.stdin.write(JSON.stringify({ jsonrpc: '2.0', id, method, params }) + '\n');
  return new Promise((resolve) => waiting.set(id, resolve));
}
const failures = [];
function check(ok, name) {
  console.log(`${ok ? 'PASS' : 'FAIL'} ${name}`);
  if (!ok) failures.push(name);
}
async function call(name, args = {}) {
  const message = await rpc('tools/call', { name, arguments: args });
  const result = message.result ?? {};
  const content = result.structuredContent ?? {};
  appendFileSync(transcript, JSON.stringify({ tool: name, arguments: args, isError: !!result.isError, result: content }) + '\n');
  return { error: result.isError ? content.error ?? content : null, content };
}
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
// One value per entry the setting's list holds (Bambu's X1C filaments hold two).
const listOf = (current, value) => String(current).split(',').map(() => value).join(',');

const init = await rpc('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'calibration-e2e', version: '1' } });
bridge.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) + '\n');
check(!!init.result, 'initialized over the stdio bridge');

let tools = [];
for (let cursor; ;) {
  const page = await rpc('tools/list', cursor ? { cursor } : {});
  tools = tools.concat(page.result.tools);
  cursor = page.result.nextCursor;
  if (!cursor) break;
}
const generate = tools.find((tool) => tool.name === 'calibration_generate');
check(!!generate, 'calibration_generate is offered over MCP');
console.log('annotations', JSON.stringify(generate?.annotations));

const printers = await call('printer_list');
console.log('printers', JSON.stringify(printers.content.items));
const before = await call('workspace_inspect', { sections: ['summary', 'printer'] });
console.log('before', JSON.stringify(before.content).slice(0, 600));

// A range Orca's dialog refuses closes nothing.
const refused = await call('calibration_generate', { test: 'temperature', start: 190, end: 230 });
check(refused.error?.code === 'invalid_argument', 'a refused range is refused: ' + refused.error?.message);

// The temperature tower.
const tower = await call('calibration_generate', { test: 'temperature', start: 230, end: 190, projectName: 'Temperature test' });
check(!tower.error && tower.content.projectName === 'Temperature test', 'temperature tower generated');
console.log('tower', JSON.stringify(tower.content));
check(tower.content.applied?.start === 230 && tower.content.applied?.end === 190 && tower.content.applied?.step === 5,
  'the tower applies 230 to 190 in 5 degree steps');
let slicing = await call('workspace_inspect', { sections: ['slicing'] });
const plate = slicing.content.slicing?.plates?.[0];
check(plate?.calibration?.test === 'temperature' && plate.calibration.start === 230, 'the workspace reports the tower\'s steps');

// Slice it, as the assistant does before asking for a print.
const sliced = await call('slice_start', { plateId: tower.content.plateId });
check(!sliced.error, 'slice started: ' + JSON.stringify(sliced.error ?? ''));
for (let tries = 0; tries < 120; ++tries) {
  slicing = await call('workspace_inspect', { sections: ['slicing'] });
  if (!slicing.content.slicing?.running && slicing.content.slicing?.plates?.[0]?.sliced) break;
  await sleep(1000);
}
check(slicing.content.slicing?.plates?.[0]?.sliced === true, 'the tower sliced');
const report = await call('slice_report', { plateId: tower.content.plateId, sections: ['summary'] });
console.log('report', JSON.stringify(report.content.summary ?? report.content).slice(0, 300));

// The result, saved as a calibrated copy of the stock filament.
const printer = (await call('workspace_inspect', { sections: ['printer'] })).content.printer;
const base = printer?.filaments?.[0]?.preset ?? before.content.printer?.filaments?.[0]?.preset;
console.log('filament in use', base, 'printer', printer?.name ?? printer?.preset);
const target = { preset: base };
const current = (await call('settings_get', { scope: 'filament', target, keys: ['nozzle_temperature'] })).content.items?.[0]?.value;
const inPlace = await call('settings_preview_patch', { scope: 'filament', target, changes: { nozzle_temperature: listOf(current, '215') }, persistAs: base });
const readOnly = (inPlace.content.issues ?? []).find((issue) => issue.code === 'read_only_preset');
check(!!readOnly, 'the stock filament cannot be overwritten: ' + (readOnly?.message ?? JSON.stringify(inPlace.content.issues)));
const printerName = printer?.name ?? 'printer';
const copy = `${base} · ${printerName} calibrated`;
const changes = { nozzle_temperature: listOf(current, '215'), nozzle_temperature_initial_layer: listOf(current, '215') };
let preview = await call('settings_preview_patch', { scope: 'filament', target, changes, persistAs: copy });
check(preview.content.valid === true, 'the calibrated copy previews: ' + JSON.stringify(preview.content.issues ?? []));
let applied = await call('settings_apply_patch', { scope: 'filament', target, changes, persistAs: copy,
  expectedSessionId: preview.content.sessionId, expectedRevision: preview.content.revision });
check(!applied.error && applied.content.savedAs === copy, 'saved as ' + copy + ' ' + JSON.stringify(applied.error ?? ''));

// A second result under the same name updates that copy.
const own = { preset: copy };
const again = { nozzle_temperature: listOf(current, '220') };
preview = await call('settings_preview_patch', { scope: 'filament', target: own, changes: again, persistAs: copy });
applied = await call('settings_apply_patch', { scope: 'filament', target: own, changes: again, persistAs: copy,
  expectedSessionId: preview.content.sessionId, expectedRevision: preview.content.revision });
check(!applied.error && applied.content.savedAs === copy, 'a second result updates the same copy');
const listed = await call('presets_list', { kind: 'filament', query: 'calibrated' });
console.log('presets', JSON.stringify(listed.content).slice(0, 400));

// The pressure-advance tower, saved into that copy without the test's own edits.
const pa = await call('calibration_generate', { test: 'pressure_advance', projectName: 'Pressure advance test' });
check(!pa.error && pa.content.applied?.method === 'tower' && pa.content.applied?.end === 0.1, 'pressure-advance tower generated with the dialog defaults');
const inUse = (await call('workspace_inspect', { sections: ['printer'] })).content.printer?.filaments?.[0]?.preset;
console.log('filament in the new test project', inUse);
const paTarget = { preset: inUse };
const paNow = (await call('settings_get', { scope: 'filament', target: paTarget, keys: ['pressure_advance', 'enable_pressure_advance'] })).content.items;
const paChanges = { enable_pressure_advance: listOf(paNow[1].value, '1'), pressure_advance: listOf(paNow[0].value, '0.032') };
preview = await call('settings_preview_patch', { scope: 'filament', target: paTarget, changes: paChanges, persistAs: inUse });
const swept = (preview.content.warnings ?? []).find((warning) => warning.code === 'saves_unsaved_edits');
check(!!swept && /slow_down_layer_time \(saved value [^)]+\)/.test(swept.message), 'the test\'s own edit is named with its saved value: ' + swept?.message);
for (const [key, value] of (swept?.message.match(/(\w+) \(saved value ([^)]+)\)/g) ?? []).map((part) => part.match(/(\w+) \(saved value ([^)]+)\)/).slice(1)))
  paChanges[key] = value;
preview = await call('settings_preview_patch', { scope: 'filament', target: paTarget, changes: paChanges, persistAs: inUse });
applied = await call('settings_apply_patch', { scope: 'filament', target: paTarget, changes: paChanges, persistAs: inUse,
  expectedSessionId: preview.content.sessionId, expectedRevision: preview.content.revision });
check(!applied.error && applied.content.savedAs === inUse, 'the pressure-advance result is saved into the copy, test edits left out');
const saved = (await call('settings_get', { scope: 'filament', target: paTarget, keys: ['pressure_advance', 'slow_down_layer_time'] })).content.items;
console.log('saved copy now', JSON.stringify(saved.map((item) => [item.key, item.value])));

console.log(failures.length ? `FAILED ${failures.length}: ${failures.join('; ')}` : 'ALL PASSED');
bridge.stdin.end();
process.exit(failures.length ? 1 : 0);

