// Names the function holding an offset from a crash, using an MSVC map file.
// Usage: node map-lookup.js <file.map> <hex offset>
const fs = require('fs');
const readline = require('readline');
const [mapPath, offsetText] = process.argv.slice(2);
const offset = BigInt('0x' + offsetText.replace(/^0x/, ''));
let base = 0x140000000n, best = null, bestAddr = -1n;
const rl = readline.createInterface({ input: fs.createReadStream(mapPath) });
rl.on('line', (line) => {
  const preferred = line.match(/Preferred load address is ([0-9a-fA-F]+)/);
  if (preferred) base = BigInt('0x' + preferred[1]);
  const m = line.match(/^\s*[0-9a-fA-F]{4}:[0-9a-fA-F]{8}\s+(\S+)\s+([0-9a-fA-F]{16})\s+(.*)$/);
  if (!m) return;
  const address = BigInt('0x' + m[2]);
  if (address - base <= offset && address > bestAddr) { bestAddr = address; best = m[1] + '  ' + m[3]; }
});
rl.on('close', () => console.log(best, '+0x' + (base + offset - bestAddr).toString(16)));

