const fs = require('fs');
const p = __dirname + '/mcp-calibration.mjs';
let s = fs.readFileSync(p, 'utf8');
function rep(a, b) { if (s.indexOf(a) < 0) throw new Error('anchor ' + a.slice(0, 60)); s = s.replace(a, b); }
rep("import { writeFileSync, appendFileSync } from 'node:fs';",
    "import { writeFileSync, appendFileSync } from 'node:fs';\nimport { execFileSync } from 'node:child_process';\nimport { fileURLToPath } from 'node:url';");
rep("const [bridgePath, discovery, transcript] = process.argv.slice(2);",
    "const [bridgePath, discovery, transcript, shots] = process.argv.slice(2);\n" +
    "// The app window from the screen at each milestone, when a folder is given.\n" +
    "function shot(name) {\n" +
    "  if (!shots) return;\n" +
    "  execFileSync('pwsh', ['-NoProfile', '-File', fileURLToPath(new URL('./shot.ps1', import.meta.url)), '-Out', `${shots}\\\\${name}.png`]);\n" +
    "}");
rep("const before = await call('workspace_inspect', { sections: ['summary', 'printer'] });",
    "const before = await call('workspace_inspect', { sections: ['summary', 'printer'] });\nshot('01-fixture-on-the-fake-a1-mini');");
rep("'the workspace reports the tower\\'s steps');",
    "'the workspace reports the tower\\'s steps');\n" +
    "check((tower.content.messages?.items ?? []).length === 0, 'no notice about the uncut test model: ' + JSON.stringify(tower.content.messages?.items ?? []));\n" +
    "shot('02-temperature-tower-generated-over-mcp');");
rep("check(slicing.content.slicing?.plates?.[0]?.sliced === true, 'the tower sliced');",
    "check(slicing.content.slicing?.plates?.[0]?.sliced === true, 'the tower sliced');\nshot('03-tower-sliced');");
rep("check(copies.length === 1, 'exactly one preset carries the copy name (' + copies.length + ')');",
    "check(copies.length === 1, 'exactly one preset carries the copy name (' + copies.length + ')');\nshot('04-saved-as-calibrated-copy');");
rep("console.log('saved copy now', JSON.stringify(saved.map((item) => [item.key, item.value])));",
    "console.log('saved copy now', JSON.stringify(saved.map((item) => [item.key, item.value])));\nshot('05-pressure-advance-saved-into-the-copy');");
fs.writeFileSync(p, s);
console.log('ok');

