.printer-menu {
  position: absolute;
  top: calc(100% + 4px);
  right: 0;
  z-index: 2;
  display: flex;
  flex-direction: column;
  gap: var(--popover-row-gap);
  min-width: max-content;
  padding: var(--popover-padding-y) 0;
  background: var(--surface-raised);
  border: var(--popover-border-width) solid var(--border-subtle);
  border-radius: var(--popover-radius);
  box-shadow: var(--elevation-medium);
}

.printer-menu button {
  display: flex;
  align-items: center;
  height: var(--menu-row-height);
  margin: 0 var(--menu-row-side-inset);
  padding: 0 12px;
  font: var(--font-body);
  color: var(--text-primary);
  text-align: left;
  white-space: nowrap;
  background: transparent;
  border: 0;
  border-radius: var(--menu-row-radius);
  cursor: pointer;
}

.printer-menu button:hover:enabled,
.printer-menu button:focus-visible {
  background: var(--surface-raised-hover);
}

/* A menu row has no focus state of its own: the keyboard's row looks like the
   hovered one. The outside ring would stick out past the popover's edge. */
.printer-menu button:focus-visible {
  outline: none;
}

.printer-menu button:disabled {
  color: var(--action-disabled-text);
  cursor: default;
}

.printer-menu button.danger:enabled {
