// A native window as it draws itself, even under other windows or with the
// desktop disconnected, where a screen blit copies whatever is on top.
bool snapshot_native_window(void* native_view, const char* path)
{
#ifndef PW_RENDERFULLCONTENT
    constexpr UINT PW_RENDERFULLCONTENT = 0x2;
#endif
    const HWND window = static_cast<HWND>(native_view);
    RECT       rect{};
    if (window == nullptr || !::GetWindowRect(window, &rect))
        return false;
    wxBitmap bitmap(rect.right - rect.left, rect.bottom - rect.top, 24);
    {
        wxMemoryDC memory(bitmap);
        if (!::PrintWindow(window, static_cast<HDC>(memory.GetHDC()), PW_RENDERFULLCONTENT))
            return false;
    }
    return bitmap.ConvertToImage().SaveFile(wxString::FromUTF8(path), wxBITMAP_TYPE_PNG);
}
#endif

