import { useEffect, useMemo, useReducer } from 'react';
import { BridgeClient, ConnectionState, Transport } from './bridge/client';
import { ProjectCard } from './components/ProjectCard';
import { PrinterCard } from './components/PrinterCard';
import type { PrinterActions } from './components/PrinterMenu';
import { PlusGlyph, UploadGlyph } from './components/Glyphs';
import { initialState, reduce } from './state/store';
import { applyAppearance } from './tokens';

// Home is the screen before a project: the gallery takes the width that is
// left, the printer column is a fixed rail. The page draws no top bar -- the
// native shell owns the header above this panel, and a second one here would
// duplicate it.
export function App({ getTransport }: { getTransport: () => Transport | null }) {
  const [state, dispatch] = useReducer(reduce, initialState);

  const client = useMemo(
    () =>
      new BridgeClient({
        getTransport,
        onEnvelope: (envelope) => dispatch({ kind: 'envelope', envelope }),
        onConnectionChange: (connection: ConnectionState, detail?: string) =>
          dispatch({ kind: 'connection', state: connection, detail }),
      }),
    [getTransport],
  );

  useEffect(() => {
    client.start();
  }, [client]);

  // Each action clears the last refusal first: its message was about the
  // previous request, not this one.
  const printerActions = useMemo<PrinterActions>(() => {
    const send = (
      type: 'open_printer_settings' | 'rename_printer' | 'remove_printer' | 'connect_printer' | 'calibrate_printer',
      payload: object,
    ) => {
      dispatch({ kind: 'printer_action' });
      client.send(type, payload);
    };
    return {
      onConnect: (id) => send('connect_printer', { id }),
      onOpenSettings: (id) => send('open_printer_settings', { id }),
      onCalibrate: (id) => send('calibrate_printer', { id }),
      onRename: (id, name) => send('rename_printer', name === undefined ? { id } : { id, name }),
      onRemove: (id) => send('remove_printer', { id }),
    };
  }, [client]);

  useEffect(() => {
    applyAppearance(state.appearance);
  }, [state.appearance]);

  if (state.connection !== 'connected' && !state.loaded) {
    return (
      <div className="app connecting">
        <h1>Connecting…</h1>
        <p>Starting Home.</p>
        {state.connectionDetail && (
          <details>
            <summary>Diagnostics</summary>
            <p className="footnote">{state.connectionDetail}</p>
          </details>
        )}
      </div>
    );
  }

  return (
// Home's state and the one reducer that advances it. The page renders what the
// host last said; it owns no project or printer state of its own, so a reload
// is always recoverable from the next `state` envelope.

import type { ConnectionState } from '../bridge/client';
import type {
  Appearance,
  Envelope,
  PrinterErrorPayload,
  PrinterInfo,
  ProjectInfo,
  StatePayload,
} from '../bridge/protocol';

export interface HomeState {
  connection: ConnectionState;
  connectionDetail?: string;
  // Absent until the host answers the handshake with state: an empty gallery
  // and "no projects yet" are different screens.
  loaded: boolean;
  appearance: Appearance;
  projects: ProjectInfo[];
  printers: PrinterInfo[];
  error?: string;
  // The last printer action the host refused. The host follows a refusal with
  // a fresh state, so only the person's next printer action clears it.
  printerError?: PrinterErrorPayload;
  // A printer the conversation just added, which the host leads the column
  // with for this one push; its card draws attention to itself once.
  highlightPrinter?: string;
}

export const initialState: HomeState = {
  connection: 'connecting',
  loaded: false,
  appearance: 'light',
  projects: [],
  printers: [],
};

export type HomeAction =
  | { kind: 'connection'; state: ConnectionState; detail?: string }
  | { kind: 'envelope'; envelope: Envelope }
  | { kind: 'printer_action' };

export function reduce(state: HomeState, action: HomeAction): HomeState {
  if (action.kind === 'connection') {
    return { ...state, connection: action.state, connectionDetail: action.detail };
  }
  if (action.kind === 'printer_action') {
    return { ...state, printerError: undefined };
  }
  const { type, payload } = action.envelope;
  switch (type) {
    case 'state': {
      const next = payload as StatePayload;
      return {
        ...state,
        loaded: true,
        appearance: next.appearance,
        projects: next.projects ?? [],
        printers: next.printers ?? [],
        error: undefined,
        highlightPrinter: next.highlightPrinter || undefined,
      };
    }
    case 'projects':
      return { ...state, projects: (payload as { projects: ProjectInfo[] }).projects ?? [] };
    case 'printers':
      return { ...state, printers: (payload as { printers: PrinterInfo[] }).printers ?? [] };
    case 'appearance':
      return { ...state, appearance: (payload as { appearance: Appearance }).appearance };
    case 'printer_error':
      return { ...state, printerError: payload as PrinterErrorPayload };
    case 'bridge_error':
      return { ...state, error: (payload as { message?: string }).message };
    default:
      return state;
  }
}
        )}
      </div>
      {dialog && (
        <div className="printer-dialog-shade">
          <div
            ref={panel}
            className="printer-dialog"
            role="dialog"
            aria-modal="true"
            aria-labelledby={`printer-dialog-title-${printer.id}`}
            onKeyDown={(event) => {
              if (event.key === 'Escape') {
                event.stopPropagation();
                closeDialog();
              }
              if (event.key === 'Tab') {
                const controls = Array.from(panel.current!.querySelectorAll<HTMLElement>('input, button:not(:disabled)'));
                const first = controls[0];
                const last = controls[controls.length - 1];
                if (event.shiftKey && document.activeElement === first) {
                  event.preventDefault();
                  last.focus();
                }
                if (!event.shiftKey && document.activeElement === last) {
                  event.preventDefault();
                  first.focus();
                }
              }
            }}
          >
            <h2 id={`printer-dialog-title-${printer.id}`}>
              {dialog === 'rename' ? 'Rename printer' : 'Remove printer?'}
            </h2>
            {dialog === 'rename' ? (
              <form
                onSubmit={(event) => {
                  event.preventDefault();
                  if (problem) return;
                  const trimmed = name.trim();
                  if (trimmed !== printer.name) actions.onRename(printer.id, trimmed);
                  closeDialog();
                }}
              >
                <label htmlFor={`printer-name-${printer.id}`}>Printer name</label>
                <input
                  id={`printer-name-${printer.id}`}
                  ref={input}
                  value={name}
                  onChange={(event) => setName(event.target.value)}
                />
                {problem && <p role="alert">{problem}</p>}
                <div className="printer-dialog-buttons">
                  <button type="button" className="button-secondary" onClick={closeDialog}>
                    Cancel
                  </button>
                  <button type="submit" className="button-primary" disabled={problem !== undefined}>
                    Save
                  </button>
                </div>
              </form>
            ) : (
              <>
                <p>
                  Remove “{printer.name}”? Its printer settings will be deleted. Your projects stay.
                </p>
                <div className="printer-dialog-buttons">
                  <button type="button" className="button-secondary" onClick={closeDialog}>
                    Cancel
                  </button>
                  <button
                    type="button"
                    className="button-danger"
                    onClick={() => {
                      actions.onRemove(printer.id);
                      closeDialog();
                    }}
                  >
                    Remove
                  </button>
                </div>
              </>
}

/* Rename and remove are the add-printer dialog's kind: the same width,
   radius, and scrim over the whole window, laid out as the design system's
   Sheet (24 padding, 16 between its parts). */
.printer-dialog-shade {
  position: fixed;
  inset: 0;
  z-index: 4;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 48px 16px 16px;
  background: color-mix(in srgb, var(--overlay-scrim) var(--printer-dialog-scrim), transparent);
}

.printer-dialog {
  display: flex;
  flex-direction: column;
  gap: 16px;
  width: 100%;
  max-width: var(--printer-dialog-width);
  padding: 24px;
  background: var(--surface-raised);
  border-radius: var(--printer-dialog-radius);
  box-shadow: var(--elevation-strong);
}

.printer-dialog h2 {
  margin: 0;
  font: var(--font-section);
  color: var(--text-primary);
}

.printer-dialog p {
  margin: 0;
  overflow-wrap: anywhere;
  font: var(--font-body);
  color: var(--text-secondary);
}

.printer-dialog p[role='alert'] {
  color: var(--status-danger);
}

.printer-dialog label {
  display: block;
  font: var(--font-label);
  color: var(--text-secondary);
}

.printer-dialog input {
  width: 100%;
  margin-top: 4px;
  padding: 8px;
  font: var(--font-body);
  color: var(--text-primary);
  background: var(--surface-canvas);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-small);
}

.printer-dialog-buttons {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

/* Inside the rename form the field's error sits under it, and the buttons
   keep the Sheet's gap from the field. */
.printer-dialog form > p {
  margin-top: 8px;
}

.printer-dialog form > .printer-dialog-buttons {
  margin-top: 16px;
}

.button-danger {
  display: inline-flex;
  align-items: center;
  font: var(--font-body-small-bold);
  padding: var(--button-primary-padding);
  border-radius: var(--radius-medium);
  color: var(--status-danger);
  background: transparent;
  border: 1px solid var(--status-danger);
  cursor: pointer;
}

.button-primary:disabled {
  color: var(--action-disabled-text);
  background: var(--action-disabled);
  cursor: default;
}

