            </h2>
            {dialog === 'rename' ? (
              <form
                onSubmit={(event) => {
                  event.preventDefault();
                  if (problem) return;
                  const trimmed = name.trim();
                  if (trimmed !== printer.name) actions.onRename(printer.id, trimmed);
                  closeDialog();
                }}
              >
                <label htmlFor={`printer-name-${printer.id}`}>Printer name</label>
                <input
                  id={`printer-name-${printer.id}`}
                  ref={input}
                  value={name}
                  onChange={(event) => setName(event.target.value)}
                />
                {problem && <p role="alert">{problem}</p>}
                <div className="printer-dialog-buttons">
                  <button type="button" className="button-secondary" onClick={closeDialog}>
                    Cancel
                  </button>
                  <button type="submit" className="button-primary" disabled={problem !== undefined}>
                    Save
                  </button>
                </div>
              </form>
            ) : (
              <>
                <p>
                  Remove “{printer.name}”? Its printer settings will be deleted. Your projects stay.
                </p>
                <div className="printer-dialog-buttons">
                  <button type="button" className="button-secondary" onClick={closeDialog}>
                    Cancel
                  </button>
                  <button
                    type="button"
                    className="button-danger"
                    onClick={() => {
                      actions.onRemove(printer.id);
                      closeDialog();
                    }}
                  >
                    Remove
                  </button>
                </div>
              </>
}

/* Rename and remove are the add-printer dialog's kind: the same width,
   radius, and scrim over the whole window, laid out as the design system's
   Sheet (24 padding, 16 between its parts). */
.printer-dialog-shade {
  position: fixed;
  inset: 0;
  z-index: 4;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 48px 16px 16px;
  background: color-mix(in srgb, var(--overlay-scrim) var(--printer-dialog-scrim), transparent);
}

.printer-dialog {
  display: flex;
  flex-direction: column;
  gap: 16px;
  width: 100%;
  max-width: var(--printer-dialog-width);
  padding: 24px;
  background: var(--surface-raised);
  border-radius: var(--printer-dialog-radius);
  box-shadow: var(--elevation-strong);
}

.printer-dialog h2 {
  margin: 0;
  font: var(--font-section);
  color: var(--text-primary);
}

.printer-dialog p {
  margin: 0;
  overflow-wrap: anywhere;
  font: var(--font-body);
  color: var(--text-secondary);
}

.printer-dialog p[role='alert'] {
  color: var(--status-danger);
}

.printer-dialog label {
  display: block;
  font: var(--font-label);
  color: var(--text-secondary);
}

.printer-dialog input {
  width: 100%;
  margin-top: 4px;
  padding: 8px;
  font: var(--font-body);
  color: var(--text-primary);
  background: var(--surface-canvas);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-small);
}

.printer-dialog-buttons {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

/* Inside the rename form the field's error sits under it, and the buttons
   keep the Sheet's gap from the field. */
.printer-dialog form > p {
  margin-top: 8px;
}

.printer-dialog form > .printer-dialog-buttons {
  margin-top: 16px;
}

.button-danger {
  display: inline-flex;
  align-items: center;
  font: var(--font-body-small-bold);
  padding: var(--button-primary-padding);
  border-radius: var(--radius-medium);
  color: var(--status-danger);
  background: transparent;
  border: 1px solid var(--status-danger);
  cursor: pointer;
}

.button-primary:disabled {
  color: var(--action-disabled-text);
  background: var(--action-disabled);
  cursor: default;
}

