        return;

    // The project chat, not the printer's: the test needs the project's tools.
    restore_task_panel();
    if (m_tabpanel->GetSelection() == MainFrame::tpHome)
        m_frame->select_tab(size_t(MainFrame::tp3DEditor));
    m_agent_pane_user_collapsed = false;
    set_agent_pane_collapsed(false);
    // The person's own words, saying what they just agreed to, so the
    // calibration skill takes over without asking it again.
    const wxString asked = filament.empty() ? wxString::Format(_L("Calibrate a filament on %s."), from_u8(printer)) :
                                              wxString::Format(_L("Calibrate %1$s on %2$s."), from_u8(filament), from_u8(printer));
    const wxString text  = asked + " " + wxString::Format(_L("I'm fine with %s being saved and closed for the test."), project);
    const std::string id = "calibrate-" + std::to_string(std::chrono::steady_clock::now().time_since_epoch().count());
    std::string refusal;
    if (host.submit_issue_message(id, into_u8(text), {}, &refusal) == Agent::AgentHost::SubmitResult::Refused)
        show_error(m_frame, _L("The chat could not take the request right now. Try again in a moment."));
}''',
'''    // A menu row has no sentence of the assistant's before it, so board 3's
    // Confirmation dialog says what the assistant would: the open project
    // closes, and the test's settings are temporary. Which test is the
    // assistant's question. The page the person is looking at asks: Home
    // for its card, the project chat for the header's rows. Nothing changes
    // until they choose Start test.
    const std::string project = m_workspace->snapshot().setup.project_name;
    const wxString    target  = filament.empty() ?
                                    wxString::Format(_L("on %s"), from_u8(printer)) :
                                    wxString::Format(_L("for %1$s on %2$s"), from_u8(filament), from_u8(printer));
    const std::string body = into_u8(wxString::Format(
        _L("%1$s will be saved and closed. A new project opens with the test %2$s. Settings the test changes are "
           "temporary, and nothing is saved to your filament until you choose a result. The assistant asks which test "
           "fits what you are seeing."),
        from_u8(project), target));
    const std::string id = "calibrate-" + std::to_string(std::chrono::steady_clock::now().time_since_epoch().count());
    m_pending_calibration = PendingCalibration{id, printer, filament, project};
    const std::string title = into_u8(_L("Start a calibration test?")), confirm = into_u8(_L("Start test")),
                      cancel = into_u8(_L("Cancel"));
    if (m_tabpanel->GetSelection() == MainFrame::tpHome) {
        m_home->host().ask_confirmation({id, title, body, confirm, cancel});
        return;
    }
    // The project chat, not the printer's: the test needs the project's tools.
    restore_task_panel();
    m_agent_pane_user_collapsed = false;
    set_agent_pane_collapsed(false);
    host.ask_confirmation({id, title, body, confirm, cancel});
}

void ShellController::answer_calibration(const std::string& request_id, bool confirmed)
{
    // An answer to a question a newer one replaced asks for nothing.
    if (!m_pending_calibration || m_pending_calibration->request_id != request_id)
        return;
    const PendingCalibration pending = std::move(*m_pending_calibration);
    m_pending_calibration.reset();
    if (!confirmed)
        return;
    restore_task_panel();
    if (m_tabpanel->GetSelection() == MainFrame::tpHome)
        m_frame->select_tab(size_t(MainFrame::tp3DEditor));
    m_agent_pane_user_collapsed = false;
    set_agent_pane_collapsed(false);
    // The person's own words, saying what they just agreed to, so the
    // calibration skill takes over without asking it again.
    const wxString printer = from_u8(pending.printer);
    const wxString asked   = pending.filament.empty() ?
                                 wxString::Format(_L("Calibrate a filament on %s."), printer) :
                                 wxString::Format(_L("Calibrate %1$s on %2$s."), from_u8(pending.filament), printer);
    const wxString text = asked + " " + wxString::Format(_L("I'm fine with %s being saved and closed for the test."),
                                                         from_u8(pending.project));
    std::string refusal;
    if (m_agent_pane->web_view().host().submit_issue_message(pending.request_id, into_u8(text), {}, &refusal) ==
        Agent::AgentHost::SubmitResult::Refused)
        show_error(m_frame, _L("The chat could not take the request right now. Try again in a moment."));
}'''),
