6455	    // since the test will close the open project: Cancel there changes
6456	    // nothing, and Start test sends the request to the project chat as the
6457	    // person's own words. The stand-in assistant then asks which test, and
6458	    // the tapped answer makes it in a project of its own.
6459	    static constexpr const char* kCalibrationPrinter = "Workshop X1C";
6460	    static constexpr const char* kCalibrationProject = "Backpack hook";
6461	
6462	    // The next modal dialog, drawn with the window behind it and answered.
6463	    void answer_next_dialog(const std::string& name, int answer)
6464	    {
6465	        m_dialog_seen.clear();
6466	        m_dialog_timer = std::make_unique<wxTimer>();
6467	        auto shown = std::make_shared<int>(0);
6468	        m_dialog_timer->Bind(wxEVT_TIMER, [this, name, answer, shown](wxTimerEvent&) {
6469	            for (wxWindow* window : wxTopLevelWindows)
6470	                if (auto* dialog = dynamic_cast<wxDialog*>(window); dialog != nullptr && dialog->IsModal()) {
6471	                    // Captured once it has painted. JUSPRIN_HARNESS_DIALOG_HOLD_MS
6472	                    // keeps it up longer, for a capture from outside the process.
6473	                    const char* hold = std::getenv("JUSPRIN_HARNESS_DIALOG_HOLD_MS");
6474	                    if (*shown < 1 + (hold != nullptr ? std::atoi(hold) / 300 : 0)) {
6475	                        ++*shown;
6476	                        return;
6477	                    }
6478	                    m_dialog_timer->Stop();
6479	                    std::function<void(wxWindow*)> read = [&](wxWindow* parent) {
6480	                        for (wxWindow* child : parent->GetChildren()) {
6481	                            if (dynamic_cast<wxStaticText*>(child) != nullptr)
6482	                                m_dialog_seen += ui_text(child->GetLabel()) + "\n";
6483	                            read(child);
6484	                        }
6485	                    };
6486	                    m_dialog_seen = ui_text(dialog->GetTitle()) + "\n";
6487	                    read(dialog);
6488	                    std::cout << "HARNESS CALIBRATION DIALOG " << name << " " << m_dialog_seen << std::endl;
6489	                    blit_screen(m_frame->GetScreenRect(), name + "-window");
6490	                    blit_screen(dialog->GetScreenRect(), name);
6491	                    dialog->EndModal(answer);
6492	                    return;
6493	                }
6494	        });
6495	        m_dialog_timer->Start(300);
6496	    }
6497	
6498	    // What a cancelled dialog must have left as it was.
6499	    struct CalibrationBefore
6500	    {
6501	        std::uint64_t session{0};
6502	        std::size_t   messages{0};
6503	    };
6504	    CalibrationBefore calibration_before() const
6505	    {
6506	        return {m_workspace_adapter().snapshot().session.value(), installed_shell()->agent_pane()->web_view().host().conversation().size()};
6507	    }
6508	    void check_untouched(const CalibrationBefore& before, const std::string& name)
6509	    {
6510	        check(m_workspace_adapter().snapshot().session.value() == before.session &&
6511	                  m_workspace_adapter().snapshot().setup.project_name == kCalibrationProject,
6512	              name + "_cancel_keeps_the_project");
6513	        check(installed_shell()->agent_pane()->web_view().host().conversation().size() == before.messages,
6514	              name + "_cancel_sends_nothing");
6515	    }
6516	    Workspace::IWorkspace& m_workspace_adapter() const { return *installed_shell()->workspace(); }
6517	
6518	    // A popup is on the screen only once the event loop has painted it.
6519	    void after_painting(const std::string& name, std::function<void()> then)
6520	    {
6521	        const auto until = std::chrono::steady_clock::now() + std::chrono::milliseconds(1000);
6522	        wait_until([until] { return std::chrono::steady_clock::now() >= until; }, name, std::move(then));
6523	    }
6524	
6525	    void begin_calibration_capture()
6526	    {
6527	        // A saved printer, so Home has a card for it and the chip names it.
6528	        SetupCommands::select_printer_preset(*m_plater, kSetupFixturePrinter);
6529	        check(Printers::add_named_printer(*m_plater, kCalibrationPrinter, {}) == kCalibrationPrinter &&
6530	                  SetupCommands::select_named_printer(*m_plater, kCalibrationPrinter),
6531	              "calibration_printer_saved_and_selected");
6532	        m_plater->set_project_name(wxString::FromUTF8(kCalibrationProject));
6533	        m_frame->select_tab(size_t(MainFrame::tp3DEditor));
6534	        installed_shell()->status_row()->refresh();
6535	        wxYield();
6536	#ifndef __APPLE__
6537	        // OrcaSlicer's own Calibration button stays out of the title bar
6538	        // while the shell is installed.
6539	        bool orca_calibration_found = false, orca_calibration_shown = false;
6540	        BBLTopbar* topbar = m_frame->topbar();
6541	        for (size_t index = 0; index < topbar->GetToolCount(); ++index)
6542	            if (wxAuiToolBarItem* item = topbar->FindToolByIndex(int(index)); item->GetLabel() == _L("Calibration")) {
6543	                orca_calibration_found = true;
6544	                orca_calibration_shown = item->GetSizerItem() != nullptr && item->GetSizerItem()->IsShown();
6545	            }
6546	        check(orca_calibration_found && !orca_calibration_shown, "calibration_orca_title_bar_button_hidden");
6547	#endif
6548	
6549	        calibration_from_symptom();
6550	    }
6551	
6552	    // Board 2: a symptom typed into the project chat, answered with the two
6553	    // facts and a choice before any test is made.
6554	    void calibration_from_symptom()
6555	    {
6556	        installed_shell()->agent_pane()->web_view().host().on_page_message(
6557	            nlohmann::json{{"protocol", Agent::Protocol::kName},
6558	                           {"version", Agent::Protocol::kVersion},
6559	                           {"id", "calibration-symptom"},
6560	                           {"type", Agent::Protocol::kUserMessage},
6561	                           {"payload", {{"clientMessageId", "calibration-symptom-c"}, {"text", CalibrationAgent::kSymptom},
6562	                                        {"attachmentIds", nlohmann::json::array()}}}}
6563	                .dump());
6564	        wait_until([this] { return assistant_reply_complete(CalibrationAgent::kSymptomReply); }, "calibration_symptom_answered",
6565	                   [self = shared_from_this()] {
6566	            self->check(self->m_workspace_adapter().snapshot().setup.project_name == kCalibrationProject,
6567	                        "calibration_symptom_makes_no_test");
6568	            self->capture_chat_pane("0-symptom-chat");
6569	            // The filament slot's row, cancelled.
6570	            installed_shell()->status_row()->open_filament_menu();
6571	            self->after_painting("calibration_filament_menu_painted", [self] { self->calibration_from_filament(); });
6572	        });
6573	    }
6574	
6575	    void calibration_from_filament()
6576	    {
6577	        HeaderMenu* menu = visible_header_menu();
6578	        auto* row = menu ? dynamic_cast<HeaderButton*>(wxWindow::FindWindowByName(ui_name("Calibrate this filament…"), menu)) : nullptr;
6579	        check(row != nullptr && row->IsEnabled(), "calibration_filament_menu_has_the_row");
6580	        if (row == nullptr) {
6581	            finish();
6582	            return;
6583	        }
6584	        blit_screen(m_frame->GetScreenRect(), "1-filament-menu");
6585	        const CalibrationBefore before = calibration_before();
6586	        answer_next_dialog("2-dialog-from-filament-cancelled", wxID_NO);
6587	        click_row(menu, row);
6588	        wxYield();
6589	        const std::string filament = ui_text(SetupCommands::current_filament().alias);
6590	        check(m_dialog_seen.find("Start a calibration test?") == 0 && m_dialog_seen.find(kCalibrationProject) != std::string::npos &&
6591	                  m_dialog_seen.find(filament) != std::string::npos && m_dialog_seen.find("temporary") != std::string::npos,
6592	              "calibration_dialog_says_the_project_closes_and_the_settings_are_temporary");
6593	        check_untouched(before, "calibration_filament");
6594	        calibration_from_home();
6595	    }
6596	
6597	    void calibration_from_home()
6598	    {
6599	        m_frame->select_tab(size_t(MainFrame::tpHome));
6600	        installed_shell()->home_view()->refresh();
6601	        const std::string kebab = std::string("document.querySelector('.printer-menu-button[aria-label=\"Actions for ") +
6602	                                  kCalibrationPrinter + "\"]')";
6603	        // The card is drawn once the page has the printers.
6604	        run_in_home_page("window.__calibrationCard = null; setTimeout(function(){ var b = " + kebab + "; if (b) { b.click(); "
6605	                         "window.__calibrationCard = 'open'; } }, 1500)");
6606	        const auto until = std::chrono::steady_clock::now() + std::chrono::milliseconds(3000);
6607	        wait_until([until] { return std::chrono::steady_clock::now() >= until; }, "calibration_home_card_menu",
6608	                   [self = shared_from_this()] {
6609	            self->blit_screen(self->m_frame->GetScreenRect(), "3-home-card-menu");
6610	            const CalibrationBefore before = self->calibration_before();
6611	            self->answer_next_dialog("4-dialog-from-home-cancelled", wxID_NO);
6612	            self->run_in_home_page("Array.prototype.filter.call(document.querySelectorAll('.printer-menu [role=menuitem]'),"
6613	                                   " function (b) { return b.textContent === 'Calibrate…'; })[0].click()");
6614	            self->wait_until([self] { return !self->m_dialog_seen.empty(); }, "calibration_home_dialog_shown", [self, before] {
6615	                self->check(self->m_dialog_seen.find(kCalibrationPrinter) != std::string::npos &&
6616	                                self->m_dialog_seen.find("with the test on") != std::string::npos,
6617	                            "calibration_home_dialog_names_the_printer_and_no_filament");
6618	                self->check_untouched(before, "calibration_home");
6619	                self->calibration_from_printer();
