  const page: PageMessageType[] = [
    'hello',
    'state_request',
    'open_project',
    'new_project',
    'import_project',
    'launch_monitor',
    'add_printer',
    'connect_printer',
    'calibrate_printer',
    'open_printer_settings',
    'rename_printer',
    'remove_printer',
  ];
  const host: HostMessageType[] = [
    'hello_ack',
    'hello_reject',
    'state',
    'projects',
    'printers',
    'appearance',
    'printer_error',
    'bridge_error',
  ];
  expect([...page].sort()).toEqual([...protocolJson.pageMessageTypes].sort());
  expect([...host].sort()).toEqual([...protocolJson.hostMessageTypes].sort());
});

