  align-self: stretch;
  max-width: 100%;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 0;
  color: var(--text-secondary);
  font: var(--font-body-small);
  background: none;
  border: none;
}

/* The design system's Swatch. The stroke keeps a white or near-background
   colour visible. */
.note-swatch {

