// A calibration test is a project of its own: the turn that made it ends with
// the project it closed, and the test's own chat opens with the app's note of
// what OrcaSlicer made, read as the app's words.
TEST_CASE("a calibration test the Agent makes is spoken about in its own project's chat", "[agent][tools][calibration]")
{
    auto agent_owner = std::make_unique<OneCallAgent>();
    OneCallAgent* agent = agent_owner.get();
    agent->call = [](const AgentRequest&) {
        return ToolRequest{"calibration_generate", json{{"test", "temperature"}, {"start", 250}, {"end", 230}}.dump()};
    };
    Harness harness{AgentServicePtr(std::move(agent_owner))};
    harness.handshake();
    harness.send_user_message("Yes, make the temperature tower.", "c-calibrate");
    const std::string asking_project = harness.persistence.document().project_id();
    harness.pump_all();
    pump_tools_to_completion(harness);
    REQUIRE(harness.workspace.calibrations == 1);
    CHECK(agent->results.empty());
    CHECK(harness.persistence.document().project_id() != asking_project);

    harness.host.pump_tools();
    const json note = (*harness.last_of_type("message_added"))["payload"]["message"];
    CHECK(note["role"] == "note");
    CHECK(note["text"].get<std::string>().find("The temperature tower is ready in this project") == 0);
    REQUIRE(harness.host.conversation().size() >= 1);
    CHECK(harness.host.conversation().front().id == note["id"]);
    harness.pump_all();

