content.content:
.turn-activity-line {
  display: flex;
  align-items: center;
  /* WebKit centres a flex button's content unless told otherwise. */
  justify-content: flex-start;
  gap: 8px;
  width: 100%;
  min-width: 0;
  padding: 4px 0;
  border: 0;
  background: none;
  color: var(--text-secondary);
  font: var(--font-label);
  text-align: left;
  cursor: pointer;
}
.turn-activity-line:disabled { cursor: default; }
/* The words shrink before the chevron does, so the chevron sits right after
   them and a long title ellipsizes. */
.turn-activity-text {
  flex: 0 1 auto;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* The running glyph turns, one revolution per spin token, so motion says
   "still going" where a still arrow could not. */
.turn-activity-spinner {
  animation: turn-activity-spin var(--turn-activity-spin-duration) linear infinite;
}

