void AgentHost::on_calibration_generated(const std::string& summary)
{
    ProjectStateDocument& document        = m_persistence.document();
    const std::string     conversation_id = document.active_conversation_id();
    // The note says what OrcaSlicer made whether or not the Agent can speak
    // about it; the calibration skill, read on demand, says what comes next.
    ConversationMessage note;
    note.id         = document.allocate_message_id();
    note.role       = MessageRole::Note;
    note.state      = MessageState::Complete;
    note.text       = summary;
    note.created_at = m_persistence.timestamp();
    document.append_message(conversation_id, note, note.created_at);
    // The chat opens without a message of the person's to title it from, so
    // it takes the test project's name, as a title the person can change.
    const std::string project = m_workspace.snapshot().setup.project_name;
    const bool        titled  = !project.empty() && document.rename_conversation(conversation_id, project, /*generated=*/true);
    m_persistence.flush();
    send_envelope(Protocol::kMessageAdded, json{{"message", message_json(note)}}.dump());
    if (titled)
        send_conversations();
    if (m_availability == AgentAvailability::Ready && m_agent && m_agent->ready() && m_session_profile.tool_names.empty())
        start_turn(note.id);
}

